function createInventory(initialRecords) {
  if (!Array.isArray(initialRecords)) {
    throw new TypeError('initialRecords must be an array');
  }

  const records = new Map();

  function normalize(record) {
    if (record === null || typeof record !== 'object' || Array.isArray(record)) {
      throw new TypeError('record must be an object');
    }
    if (typeof record.id !== 'string' || record.id.trim() === '') {
      throw new TypeError('record.id must be a nonempty string');
    }
    if (typeof record.label !== 'string' || record.label.trim() === '') {
      throw new TypeError('record.label must be a nonempty string');
    }
    if (!Number.isSafeInteger(record.quantity) || record.quantity < 0) {
      throw new TypeError('record.quantity must be a nonnegative integer');
    }
    return { id: record.id.trim(), label: record.label.trim(), quantity: record.quantity };
  }

  function add(record) {
    const normalized = normalize(record);
    if (records.has(normalized.id)) {
      throw new Error(`Duplicate id: ${normalized.id}`);
    }
    records.set(normalized.id, normalized);
    return { ...normalized };
  }

  function list() {
    return Array.from(records.values(), record => ({ ...record }));
  }

  function find(id) {
    if (typeof id !== 'string' || !records.has(id)) return null;
    return records.get(id);
  }

  initialRecords.forEach(add);
  return { list, find, add };
}

module.exports = { createInventory };

