'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepEqual(Object.keys(api).sort(), ['createInventory']);
const { createInventory } = api;

assert.throws(() => createInventory(null), TypeError);
assert.throws(() => createInventory({}), TypeError);
assert.throws(() => createInventory([null]), TypeError);
assert.throws(() => createInventory([[]]), TypeError);
assert.throws(() => createInventory([{ id: '', label: 'Label', quantity: 0 }]), TypeError);
assert.throws(() => createInventory([{ id: 'x', label: '   ', quantity: 0 }]), TypeError);
assert.throws(() => createInventory([{ id: 'x', label: 'Label', quantity: -1 }]), TypeError);
assert.throws(() => createInventory([{ id: 'x', label: 'Label', quantity: 1.5 }]), TypeError);
assert.throws(() => createInventory([{ id: 'x', label: 'Label', quantity: Number.MAX_SAFE_INTEGER + 1 }]), TypeError);
assert.throws(
  () => createInventory([
    { id: ' item ', label: 'One', quantity: 1 },
    { id: 'item', label: 'Two', quantity: 2 }
  ]),
  error => error instanceof Error && error.message === 'Duplicate id: item'
);

const empty = createInventory([]);
assert.deepEqual(empty.list(), []);
assert.equal(empty.find('anything'), null);

const initial = [
  { id: ' drill ', label: ' Cordless Drill ', quantity: 2 },
  { id: 'saw', label: 'Saw', quantity: 0 }
];
const inventory = createInventory(initial);
assert.deepEqual(inventory.list(), [
  { id: 'drill', label: 'Cordless Drill', quantity: 2 },
  { id: 'saw', label: 'Saw', quantity: 0 }
]);
initial[0].id = 'changed';
initial[0].label = 'Changed';
initial[0].quantity = 99;
initial.push({ id: 'extra', label: 'Extra', quantity: 1 });
assert.deepEqual(inventory.find('drill'), { id: 'drill', label: 'Cordless Drill', quantity: 2 });
assert.equal(inventory.find(' drill '), null);
for (const invalidId of [null, undefined, 1, '', [], {}]) assert.equal(inventory.find(invalidId), null);

const found = inventory.find('drill');
found.label = 'Damaged';
found.quantity = 100;
assert.deepEqual(inventory.find('drill'), { id: 'drill', label: 'Cordless Drill', quantity: 2 });

const listed = inventory.list();
assert.notStrictEqual(listed, inventory.list());
assert.notStrictEqual(listed[0], inventory.list()[0]);
listed.reverse();
listed[0].label = 'Mutated';
assert.deepEqual(inventory.list(), [
  { id: 'drill', label: 'Cordless Drill', quantity: 2 },
  { id: 'saw', label: 'Saw', quantity: 0 }
]);

const record = { id: ' hammer ', label: ' Claw Hammer ', quantity: 3 };
const added = inventory.add(record);
assert.deepEqual(added, { id: 'hammer', label: 'Claw Hammer', quantity: 3 });
record.label = 'Changed input';
added.label = 'Changed output';
assert.deepEqual(inventory.find('hammer'), { id: 'hammer', label: 'Claw Hammer', quantity: 3 });
assert.deepEqual(inventory.list().map(record => record.id), ['drill', 'saw', 'hammer']);
assert.throws(
  () => inventory.add({ id: ' hammer ', label: 'Duplicate', quantity: 1 }),
  error => error instanceof Error && error.message === 'Duplicate id: hammer'
);
assert.throws(() => inventory.add({ id: 'new', label: 'New', quantity: NaN }), TypeError);
assert.equal(inventory.find('new'), null);

